#include <iostream>
#include <string>
using namespace std;

// 基类：把「所有学生都有的东西」放在这里，派生类不用重复写一遍
class Person {
protected:
    // protected 的意思是：类外面碰不到，但派生类里可以直接当自己的成员用。
    // 如果写成 private，下面 Student::study 里的 name 会编译报错。
    string name;

public:
    Person(const string& n) : name(n) {}

    void whoAmI() {
        cout << "Person: " << name << endl;
    }
};

// 冒号后面的 public 是「继承方式」，读作「Student 是一种 Person」。
// 最容易漏的就是这个 public：漏掉默认是 private 继承，
// 基类的公有成员在 main 里就调不到了（报错信息通常很难看懂）。
class Student : public Person {
public:
    // 派生类自己没办法直接初始化基类的 name，
    // 必须用初始化列表把参数转交给基类构造函数
    Student(const string& n) : Person(n) {}

    void study() {
        // name 是基类的 protected 成员，派生类里直接用就行
        cout << "Student: " << name << " is studying" << endl;
    }
};

int main() {
    string n;
    cin >> n;

    Student s(n);
    s.whoAmI();   // 基类写好的成员函数，派生类对象可以直接调用
    s.study();    // 派生类自己新增的成员函数
    return 0;
}

