#include <iostream>
#include <string>
using namespace std;

class Person {
protected:
    string name;

public:
    // 这个构造函数没有默认值，也就是说 Person 没有「默认构造函数」。
    // 派生类必须显式调用它，编译器不会替你猜名字。
    Person(const string& n) : name(n) {
        // 基类子对象先构造，所以这行一定最先打印
        cout << "Base ctor: " << name << endl;
    }
};

class Student : public Person {
    int age;

public:
    // 初始化列表的真实顺序：先基类 Person(n)，再自己的成员 age(a)，
    // 最后才进入函数体。这个顺序由语言规定，和你写的先后无关。
    Student(const string& n, int a) : Person(n), age(a) {
        cout << "Derived ctor: " << age << endl;
    }

    void info() {
        // name 来自基类，age 来自自己，派生类里都能直接读
        cout << "Student " << name << " is " << age << endl;
    }
};

int main() {
    string n;
    int a;
    cin >> n >> a;

    Student s(n, a);
    s.info();
    return 0;
}

