#include <iostream>
#include <string>
using namespace std;

class Base {
public:
    // 注意：这里没有 virtual。
    // 于是「调用哪一个 show」在编译期就被定死了，只看你用哪种类型去调。
    void show() {
        cout << "Base::show" << endl;
    }
};

class Derived : public Base {
    string name;

public:
    Derived(const string& n) : name(n) {}

    // 名字、参数、返回值都和基类一模一样，这叫覆盖。
    // 但覆盖只影响「用派生类类型去调」的情况，管不了基类指针。
    void show() {
        cout << "Derived::show " << name << endl;
    }
};

int main() {
    string n;
    cin >> n;

    Derived d(n);

    // 1）变量本身的类型是 Derived，找到的就是 Derived::show
    d.show();

    // 2）p 的静态类型是 Base*。它确实指向一个 Derived 对象，
    //    但没有 virtual 时编译器根本不看这一点，照样调用 Base::show。
    Base* p = &d;
    p->show();

    // 3）货真价实的 Base 对象，当然是 Base::show
    Base b;
    b.show();

    return 0;
}

