#include <iostream>
#include <string>
using namespace std;

class Animal {
public:
    // virtual 是这题的全部关键：它告诉编译器
    //「别在编译期把调用定死，运行期看对象真实类型再选」。
    virtual void speak() {
        cout << "Some sound" << endl;
    }
};

class Dog : public Animal {
public:
    // 基类里是虚函数，派生类里同名同参的函数自动也是虚函数，
    // 可以省略 virtual，但写上更清楚（下一题还会介绍 override）。
    void speak() {
        cout << "Woof" << endl;
    }
};

class Cat : public Animal {
public:
    void speak() {
        cout << "Meow" << endl;
    }
};

class Cow : public Animal {
public:
    void speak() {
        cout << "Moo" << endl;
    }
};

int main() {
    int n;
    cin >> n;

    // 先把可能用到的对象都建好，下面只用「指针指向谁」来区分行为
    Dog dog;
    Cat cat;
    Cow cow;
    Animal unknown;   // 不认识的单词就指向它

    for (int i = 0; i < n; i++) {
        string kind;
        cin >> kind;

        // p 的类型永远是 Animal*，它自己不知道指向的是什么。
        // 默认指向基类对象，保证任何输入都有对象可指。
        Animal* p = &unknown;
        if (kind == "dog") {
            p = &dog;
        } else if (kind == "cat") {
            p = &cat;
        } else if (kind == "cow") {
            p = &cow;
        }

        // 同样是这一行代码，输出却随对象的真实类型变化 —— 这就是多态。
        // 把 virtual 去掉，它会永远输出 Some sound。
        p->speak();
    }
    return 0;
}

