#include <iostream>
using namespace std;

class Shape {
public:
    // 虚函数：派生类可以覆盖它，用基类指针调用时会走到派生类的版本。
    // 注意签名里的 const —— 它是签名的一部分，派生类必须一致。
    virtual int area() const {
        return 0;
    }

    // 只要有虚函数，就顺手把析构函数也写成 virtual。
    // 这题没有 new/delete，但这是必须养成的习惯（下一题会看到原因）。
    virtual ~Shape() {}
};

class Rect : public Shape {
    int w, h;

public:
    Rect(int width, int height) : w(width), h(height) {}

    // override 让编译器帮你检查一致性：
    // 如果基类里没有一个 int area() const 能被覆盖，这一行直接编译失败。
    // 比如漏掉 const，报错内容大致是
    //   'area' marked 'override' but does not override any member functions
    int area() const override {
        return w * h;
    }
};

int main() {
    int w, h;
    cin >> w >> h;

    Rect r(w, h);

    // 用基类指针调用虚函数 → 实际执行的是 Rect::area
    Shape* p = &r;
    cout << p->area() << endl;
    return 0;
}

tutorial.code:
class Rect : public Shape {
public:
    // 漏了 const → 不是覆盖
    int area() override { return w * h; }   // 编译失败
};

class Shape {
public:
    virtual int area() const { return 0; }   // virtual 写在基类
};

class Rect : public Shape {
public:
    int area() const override { return w * h; }   // override 写在派生类
};

