#include <iostream>
#include <string>
#include <iomanip>
using namespace std;

// 抽象基类：只要有一个纯虚函数，这个类就不能创建对象。
// 它的作用是规定一份契约：凡是「图形」，都必须能算面积、都必须有名字。
class Shape {
public:
    // = 0 表示纯虚函数：基类给不出合理实现（「图形的面积」本身无从谈起），
    // 谁派生谁负责实现。
    virtual double area() const = 0;
    virtual string name() const = 0;

    // 用基类指针 delete 派生类对象时，析构函数必须是虚的，
    // 否则只调用基类析构，派生类自己的部分不会释放（未定义行为）。
    virtual ~Shape() {}
};

class Rect : public Shape {
    double w, h;

public:
    Rect(double width, double height) : w(width), h(height) {}

    // 纯虚函数必须全部实现，漏一个 Rect 就还是抽象类，new Rect(...) 会编译失败
    double area() const override { return w * h; }
    string name() const override { return "rect"; }
};

class Circle : public Shape {
    double r;

public:
    Circle(double radius) : r(radius) {}

    // 注意 3.14159 是浮点数，整个表达式按小数运算，不会发生整数除法
    double area() const override { return 3.14159 * r * r; }
    string name() const override { return "circle"; }
};

int main() {
    int n;
    cin >> n;

    // 数组里存的是「指向基类的指针」：
    // 它们可以指向任何派生类对象，多态就靠这一点成立
    Shape* shapes[10];

    for (int i = 0; i < n; i++) {
        string kind;
        cin >> kind;   // cin 会自动跳过换行和空格，逐行读很省心

        if (kind == "rect") {
            double w, h;
            cin >> w >> h;
            shapes[i] = new Rect(w, h);
        } else {
            double r;
            cin >> r;
            shapes[i] = new Circle(r);
        }
    }

    // fixed + setprecision(2)：保留 2 位小数，设置一次后面一直有效
    cout << fixed << setprecision(2);
    for (int i = 0; i < n; i++) {
        // 同一行代码，对不同的真实对象走进不同的实现
        cout << shapes[i]->name() << " area = " << shapes[i]->area() << endl;
    }

    // 每个 new 都要有对应的 delete。
    // 因为析构函数是虚的，这里会先跑派生类析构再跑基类析构。
    for (int i = 0; i < n; i++) {
        delete shapes[i];
    }
    return 0;
}

